function SitelinkHub(){return <section className="section sitelink-hub" aria-labelledby="sitelinks-title"><div className="sitelink-heading"><span className="eyebrow">JELAJAHI BISABIKINWEB</span><h2 id="sitelinks-title">Temukan layanan website yang kamu butuhkan.</h2><p>Pilih layanan, bandingkan harga, lihat proyek, atau mulai konsultasi melalui halaman yang jelas dan mudah ditemukan.</p></div><nav className="sitelink-grid" aria-label="Halaman utama layanan BisaBikinWeb">{sitelinkTargets.map(({href,label,description})=><a className="sitelink-card" key={href} href={href}><span>{label}</span><p>{description}</p><ArrowUpRight size={19} aria-hidden="true"/></a>)}</nav></section>}
function SectionHeading({tag,title,href,label,desc}:{tag:string,title:string,href?:string,label?:string,desc?:string}){return <div className="section-heading"><div><span className="eyebrow">{tag}</span><h2>{title}</h2>{desc&&<p>{desc}</p>}</div>{href&&<a className="text-link" href={href}>{label||'Explore more'}<ArrowUpRight size={17}/></a>}</div>}
function Services({items}:{items:any[]}){return <div className="services-grid">{items.map((s:any)=><a href={'/jasa/'+s.id} className="service-card" key={s.id}><div className="service-top"><span className="service-icon">{s.icon}</span><ArrowUpRight size={20}/></div><small>{s.tag}</small><h3>{s.name}</h3><p>{s.description}</p><div className="service-features">{s.features.slice(0,3).map((x:string)=><span key={x}>{x}</span>)}</div></a>)}</div>}
function Pricing({items}:{items:any[]}){const [mode,setMode]=useState(false);return <><div className="pricing-toggle"><button className={!mode?'selected':''} onClick={()=>setMode(false)}>Sekali bayar</button><button className={mode?'selected':''} onClick={()=>setMode(true)}>Maintenance</button></div><div className="pricing-grid">{items.map((p:any)=><div className={'price-card '+(p.featured?'featured':'')} key={p.id}>{p.featured&&<span className="popular-label">ROOM TO GROW ↗</span>}<small>{p.name.toUpperCase()}</small><h3>{(mode?p.maintenance:p.price)?money(mode?p.maintenance:p.price):p.id==='custom'?"Let's Talk":'Sesuai kebutuhan'}</h3><span className="price-note">{(mode?p.maintenance:p.price)?mode?'per bulan':'mulai dari / project':'Minta penawaran'}</span><p>{p.desc}</p><div>{p.features.map((x:string)=><p className="price-feature" key={x}><Check size={15}/>{x}</p>)}</div><a href={'/kontak?estimate='+encodeURIComponent('Saya ingin konsultasi paket '+p.name+(mode?' maintenance':''))} className={'btn '+(p.featured?'primary':'')} onClick={()=>event('pricing_click')}>{p.id==='custom'?'Konsultasikan Project':'Pilih '+p.name}<ArrowUpRight size={16}/></a></div>)}</div><p className="pricing-disclaimer">Scope, revisi, domain, hosting, dan biaya integrasi dirinci dalam penawaran. Harga final disepakati sebelum project dimulai.</p></>}
function PortfolioGrid({items,filters=false}:{items:any[],filters?:boolean}){const [filter,setFilter]=useState('All');const list=['All','Company Profile','E-commerce','Landing Page','Web App','Experimental'];return <>{filters&&<div className="filters">{list.map(x=><button key={x} className={filter===x?'active':''} onClick={()=>setFilter(x)}>{x}</button>)}</div>}<div className="portfolio-grid">{items.filter(x=>filter==='All'||x.category===filter).map((p:any)=><a className="project-card" key={p.id} href={p.live||'/portfolio/'+p.id} target={p.live?'_blank':undefined} rel={p.live?'noopener noreferrer':undefined}><PortfolioVisual project={p}/><div className="project-caption"><div><small>{p.tag}</small><h3>{p.name}</h3></div><div>{p.year&&p.year!=='—'&&<span>{p.year}</span>}<span className="circle-link"><ArrowUpRight size={20}/></span></div></div></a>)}</div>{!items.some(x=>filter==='All'||x.category===filter)&&<div className="empty"><Layers/><h3>Belum ada project yang dipublikasikan di kategori ini.</h3><button className="btn" onClick={()=>setFilter('All')}>Lihat semua project</button></div>}</>}
function EditorialText({text}:{text:string}){return <>{String(text).split(/(https:\/\/[^\s<>]+)/g).map((part,i)=>{if(!part.startsWith('https://'))return part;try{const clean=part.replace(/[.,;!?]+$/,'');const suffix=part.slice(clean.length);const url=new URL(clean);if(url.protocol!=='https:'||url.username||url.password)return part;return <span key={i}><a href={url.href} target="_blank" rel="noopener noreferrer" style={{textDecoration:'underline',overflowWrap:'anywhere'}}>{clean}</a>{suffix}</span>}catch{return part}})}</>}
function articleImage(a:any){const image=String(a.image||a.cover_image_url||'');try{const url=new URL(image);return url.protocol==='https:'&&!url.username&&!url.password?url.href:''}catch{return ''}}
function instagramPostUrl(a:any){const candidate=String(a?.instagram_post_url||'').trim();return /^https:\/\/www\.instagram\.com\/p\/[A-Za-z0-9_-]{5,20}\/$/.test(candidate)?candidate:''}
function InstagramOriginal({article}:{article:any}){const url=instagramPostUrl(article);if(!url)return null;return <figure className="article-instagram-original" style={{maxWidth:560,margin:'24px auto 36px',textAlign:'center'}}><div style={{textAlign:'left',marginBottom:12}}><strong>Visual asli dari Instagram</strong><p>Unggahan {article.instagram_post_account||'akun sumber'} — ditampilkan melalui Instagram, bukan foto yang disalin.</p></div><iframe title={'Unggahan Instagram terkait '+article.title} loading="lazy" width="100%" height="650" src={url+'embed/'} style={{display:'block',maxWidth:540,border:0,margin:'0 auto'}} referrerPolicy="strict-origin-when-cross-origin" sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox"/><figcaption><a href={url} target="_blank" rel="noopener noreferrer">Lihat unggahan asli di Instagram ↗</a><p>Jika sematan tidak muncul, buka tautan sumber. Hak gambar tetap milik pengunggah.</p></figcaption></figure>}
function articleDate(value:string){const date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Jakarta'})}
function Articles({items}:{items:any[]}){return <div className="article-grid">{items.map((a:any,i:number)=><a className="article-card" key={a.id} href={'/artikel/'+a.id+'/'}><div className={'article-visual av-'+i%3}>{articleImage(a)?<img className="article-cover" src={articleImage(a)} alt={a.image_alt||a.title} loading={i===0?'eager':'lazy'} decoding="async" width="800" height="500"/>:<><span className="article-placeholder-label">{isNewsArticle(a)?'BISABIKINWEB / BERITA':'BISABIKINWEB / JOURNAL'}</span><span>{a.category||'Insight'}<br/><em>{isNewsArticle(a)?'Kabar terkini.':'Ide untuk bertumbuh.'}</em></span><ArrowUpRight aria-hidden="true"/></>}</div><div className="article-card-copy"><div className="article-meta"><span>{a.category||'Insight'}</span><span>{a.read||'3 menit'}</span></div><h3>{a.title}</h3><p>{a.summary}</p><div className="article-card-bottom">{articleDate(a.published_at)&&<time dateTime={a.published_at}>{articleDate(a.published_at)}</time>}<span className="text-link">{isNewsArticle(a)?'Baca berita':'Baca artikel'} <ArrowUpRight size={16}/></span></div></div></a>)}</div>}
